import boto3
from boto3.s3.transfer import TransferConfig

s3 = boto3.client("s3")
BUCKET = "media-uploads"  # example bucket
MB = 1024 * 1024

def upload_url(user_id: str, upload_id: str, content_type: str) -> str:
    key = f"raw/{user_id}/{upload_id}"  # the server picks the key, never the client
    return s3.generate_presigned_url(
        "put_object",
        Params={"Bucket": BUCKET, "Key": key, "ContentType": content_type},
        ExpiresIn=900,  # 15 min: a presigned URL is a bearer token
    )

def download_url(key: str) -> str:
    return s3.generate_presigned_url(
        "get_object", Params={"Bucket": BUCKET, "Key": key}, ExpiresIn=300
    )

# Server-side large file: the SDK splits it into parallel parts
cfg = TransferConfig(
    multipart_threshold=100 * MB,  # AWS suggests multipart from ~100 MB
    multipart_chunksize=100 * MB,
    max_concurrency=8,
)
s3.upload_file("render.mp4", BUCKET, "renders/2026/render.mp4", Config=cfg)
